#include "records_screen.hh"
#include "config.h"
#include "game_state.hh"

#include <new>

inline void RecordsScreenPageList::Push(RecordsScreenPageEntry const & entry)
{
    if (count < CAPACITY) {
        new (End()) RecordsScreenPageEntry(entry);
        ++count;
    }
}

asm_unified(
    ".text\n"
    ".include \"asm/macro.inc\"\n"
    ".include \"asm/gba.inc\"\n"
);
RecordsScreenCore::RecordsScreenCore(GameStateSaveImage * image)
    : ScrollMenu(0), save(image), pages()
{
    RecordsScreenPageEntry entry;
    entry.page = PAGE_SHIPPING;
    pages.Push(entry);
    entry.page = PAGE_FISHING;
    pages.Push(entry);
    entry.page = PAGE_OTHER;
    pages.Push(entry);
    selected_page = 0;
    SelectPage(pages[0].page);
}


RecordsScreenPage::RecordsScreenPage(ScrollMenu * menu, GameStateSaveImage * image,
    u32 rows, char const * title)
    : ScrollMenuPage(menu, reinterpret_cast<u32>(image), rows, title)
{
}

RecordsScreenPage::~RecordsScreenPage()
{
}

u32 RecordsScreenPage::Draw()
{
    u32 index = 0;
    while (text_rows[index].y >= 0 && text_rows[index].y + 48 < scroll_position) {
        text_rows[index].rendered = false;
        ++index;
    }
    for (; text_rows[index].y >= 0; ++index) {
        if (text_rows[index].y <= scroll_position + 160) {
            if (!text_rows[index].rendered) {
                u32 buffer = text_rows[index].buffer_index;
                text_buffers[buffer].Clear();
                text_buffers[buffer].DrawString(0, 0, text_rows[index].text);
                text_rows[index].rendered = true;
            }
        } else {
            text_rows[index].rendered = false;
        }
    }
    ScrollMenuPage::Draw();
    return 1;
}

