u32 RecordsScreenPage::GetBestMinigameSprite(HarvestSprite::Task task) const
{
    u32 experience = 0;
    u32 best = 0;
    for (i32 i = 0; i < 7; ++i) {
        GameStateSaveImage const * save = reinterpret_cast<GameStateSaveImage const *>(context);
        HarvestSprite const * sprite = save->npcs.GetHarvestSpriteByIndex(i);
        if (sprite != nullptr) {
            u32 current = sprite->GetMinigameExp(task);
            if (experience < current) {
                best = i;
                experience = current;
            }
        }
    }
    return best;
}

void RecordsScreenCore::SelectPage(u32 page)
{
    ScrollMenuPageOwner selected;

    switch (static_cast<i32>(page))
    {
    case PAGE_SHIPPING:
        selected = new ShippingRecordsPage(this, this->save);
        break;

    case PAGE_FISHING:
        selected = new FishingRecordsPage(this, this->save);
        break;

    case PAGE_OTHER:
        selected = new OtherRecordsPage(this, this->save);
        break;
    }

    SetScrollMenuPage(this, selected);
}

